import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/index.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

// @spec specs/hal-engine-config-hooks/spec.md#8
it('reports a thrown string as the error cause while preserving the rejection', async () => {
  const errors: Error[] = [];
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Test assistant'}),
    undefined,
    {
      hooks: {
        beforeSession: async () => Promise.reject('session unavailable'),
        onError: async (_session, error) => void errors.push(error),
      },
    }
  );

  const rejection: unknown = await orchestrator
    .processMessage({sessionId: 's1', userId: 'u1', entries: []})
    .catch((error: unknown) => error);

  expect({rejection, errors}).toEqual({
    rejection: 'session unavailable',
    errors: [new Error('session unavailable', {cause: 'session unavailable'})],
  });
  expect(errors[0]?.cause).toBe('session unavailable');
});
EOF
NODE_OPTIONS=--experimental-vm-modules timeout 300 npx jest --runInBand --runTestsByPath src/orchestration/onErrorCause.test.ts"
